export interface ProjectWatchEvent {
    changeKind: ProjectWatchChangeKind
    path: string
}

export type ProjectWatchNotification = ProjectWatchEvent | { error: string }

/** A background agent/action currently running against a card or file. */
export interface RunningAgent {
    id: string
    label: string
}

export type AgentConversationStatus = 'cancelled' | 'completed' | 'failed' | 'running' | 'waitingForInput'
export type AgentMessageRole = 'assistant' | 'user'

export interface AgentConversationMessage {
    agent?: string
    content: string
    id: string
    role: AgentMessageRole
    sequence?: number
    timestamp: string
}

export interface AgentProviderUsageBaseline {
    costUsd?: number
    resultId?: string
    tokens?: AgentTokenUsage
}

export interface AgentProviderSession {
    /** Missing means the agent's initial account. */
    accountId?: string
    agent: string
    conversationId: string
    createdAt: string
    lastUsedAt: string
    synchronizedThroughMessageId: string
    usageBaseline?: AgentProviderUsageBaseline
}

export interface AgentQuestionOption {
    description?: string
    label: string
}

export interface AgentQuestion {
    header: string
    id: string
    isSecret?: boolean
    options?: AgentQuestionOption[] | null
    question: string
}

export interface AgentConversationEvent {
    command?: string
    content: string
    deletions?: number
    details?: string[]
    durationMs?: number
    exitCode?: number
    id: string
    insertions?: number
    label?: string
    output?: string
    paths?: string[]
    parentItemId?: string
    providerItemId?: string
    /** Only on an `agentQuestion` entry: the questions the agent asked, restored after a restart. */
    questions?: AgentQuestion[]
    runningSubThreads?: number
    sequence?: number
    status?: string
    summary?: string[]
    timestamp: string
    type: string
    workingDirectory?: string
}

export interface AgentConversationMessageEntry extends AgentConversationMessage {
    kind: 'message'
}

export interface AgentConversationEventEntry extends AgentConversationEvent {
    kind: 'event'
}

export type AgentConversationEntry = AgentConversationMessageEntry | AgentConversationEventEntry

export interface AgentTokenUsage {
    cachedInputTokens: number
    costUsd?: number
    inputTokens: number
    legacyTotalTokens?: number
    outputTokens: number
    reasoningTokens: number
    totalTokens: number
}

export interface AgentContextWindowUsage {
    capacityTokens: number
    usedTokens: number
}

export type AgentTaskStatus = 'pending' | 'inProgress' | 'completed'

export interface AgentTask {
    activeForm?: string
    id: string
    status: AgentTaskStatus
    subject: string
}

export interface AgentTaskList {
    tasks: AgentTask[]
    updatedAt: string
}

/** Duration components of the measured total; absent on a conversation recorded before they existed. */
export interface AgentConversationTimerBreakdown {
    reasoningMs: number
    toolMs: number
}

export interface AgentConversationTimer {
    breakdown?: AgentConversationTimerBreakdown
    elapsedMs: number
    runningStartedAt: string | null
}

export interface AgentConversation {
    actionId?: string | null
    cardInternalId?: string | null
    cardPath: string | null
    completedAt: string | null
    contextWindowUsage?: AgentContextWindowUsage
    entries: AgentConversationEntry[]
    hasExplicitTitle: boolean
    id: string
    path: string
    providerSessions: AgentProviderSession[]
    startedAt: string
    status: AgentConversationStatus
    taskList?: AgentTaskList
    timer?: AgentConversationTimer
    title: string
    usage?: AgentTokenUsage
    usageSchemaVersion?: number
    viewed: boolean
}

export interface AgentConversationError {
    /** Set when the failure came from an onState action instead of an activity file load. */
    kind?: 'onStateAction'
    message: string
    /** Activity file that failed to load, or the action id for an onState action failure. */
    path: string
}

export type AgentRunEvent =
    | {
        conversation: AgentConversation
        runId: string
        type: 'started'
    }
    | {
